1: """Deterministic tests for source-labeled location access context."""
2: 
3: import from services.models { Restaurant, Location, HasLocation }
4: import from services.context_models { ContextNotice, ContextValidationError, Affects }
5: import from services.importer { upsert_access_notice }
6: 
7: 
8: def _location(slug: str) -> Location {
9:     r = Restaurant(slug=slug, name=slug + " (Demo)", is_demo=True);
10:     root ++> r;
11:     r +>:HasLocation():+> Location(address="Fictional address", neighborhood="Demo");
12:     return [r ->:HasLocation:->][0];
13: }
14: 
15: 
16: def _record(slug: str, source: str = "test-source", external: str = "notice-1") -> dict[str, any] {
17:     return {
18:         "source_id": source, "external_id": external, "location_slug": slug,
19:         "version": "1", "publisher": "Test publisher", "source_url": "",
20:         "checked_at": 100.0, "valid_from": 100.0, "valid_until": 200.0,
21:         "summary": "Simulated test notice", "is_demo": True,
22:         "entrance_instruction": "Confirmed only in this test"
23:     };
24: }
25: 
26: 
27: test "empty_context_is_unknown_not_clear_access" {
28:     loc = _location("empty-context");
29:     context = get_access_context(jid(loc), 150.0);
30:     assert context.state == "none";
31:     assert context.notices == [];
32: }
