35: test "upsert_is_idempotent" {
36:     loc = _location("idempotent-context");
37:     record = _record("idempotent-context", "test-idempotent", "one");
38:     first = upsert_access_notice(record);
39:     second = upsert_access_notice(record);
40:     assert first == second;
41:     assert len([root-->[?:ContextNotice, source_id == "test-idempotent", external_id == "one"]]) == 1;
42:     assert len(get_access_context(jid(loc), 150.0).notices) == 1;
43: }
