89: test "notice_boundary_and_freshness" {
90:     loc = _location("boundary-context");
91:     upsert_access_notice(_record("boundary-context", "test-boundary", "one"));
92:     assert get_access_context(jid(loc), 150.0).state == "current";
93:     assert get_access_context(jid(loc), 200.0).state == "needs_recheck";
94:     assert get_access_context(jid(loc), 99.0).state == "needs_recheck";
95:     stale = _record("boundary-context", "test-stale", "one");
96:     stale["checked_at"] = 150.0 - 86401.0;
97:     stale["valid_from"] = 0.0;
98:     stale["valid_until"] = 200.0;
99:     stale_id = upsert_access_notice(stale);
100:     future = _record("boundary-context", "test-future", "one");
101:     future["checked_at"] = 151.0;
102:     future_id = upsert_access_notice(future);
103:     context = get_access_context(jid(loc), 150.0);
104:     for notice_id in [stale_id, future_id] {
105:         view = [v for v in context.notices if v.id == notice_id][0];
106:         assert view.state == "needs_recheck" and view.entrance_instruction == "";
107:     }
108:     stale["checked_at"] = 150.0 - 86400.0;
109:     upsert_access_notice(stale);
110:     fresh = [v for v in get_access_context(jid(loc), 150.0).notices if v.id == stale_id][0];
111:     assert fresh.state == "current";
112: }
