147: test "invalid_provenance_or_identity_cannot_partially_refresh_a_notice" {
148:     loc = _location("invalid-metadata-context");
149:     record = _record("invalid-metadata-context", "metadata", "one");
150:     notice_id = upsert_access_notice(record);
151:     for field in ["original_evidence", "normalized_evidence", "owner_actor_id", "merchant_key", "password", "role", "roles"] {
152:         bad = _record("invalid-metadata-context", "metadata", "one");
153:         bad["summary"] = "Must never replace the saved summary";
154:         bad["checked_at"] = 140.0;
155:         bad[field] = "untrusted-value";
156:         rejected = False;
157:         try { upsert_access_notice(bad); } except ContextValidationError { rejected = True; }
158:         assert rejected, field;
159:         context = get_access_context(jid(loc), 150.0);
160:         assert context.notices[0].id == notice_id;
161:         assert context.notices[0].summary == "Simulated test notice";
