192: test "real_notice_cannot_create_or_refresh_a_fictional_association" {
193:     loc = _location("fictional-source-context");
194:     record = _record("fictional-source-context", "source-boundary", "one");
195:     record["is_demo"] = False;
196:     record["source_url"] = "https://example.test/reviewed-notice";
