1: """PromoPusher graph schema.
2: 
3: Restaurant -HasLocation-> Location
4: Restaurant -Serves-> MenuItem
5: Restaurant -Publishes-> Offer -Features-> MenuItem
6: Offer -ClaimedAs-> Redemption
7: 
8: Times are epoch seconds (float); display is converted to Ann Arbor local time.
9: """
10: 
11: import os;
12: import from services.qr_auth { merchant_owner }
13: 
14: 
15: """Name shown to students and merchants. Stored rows may keep a fixture suffix."""
16: def public_name(name: str) -> str {
17:     return name.replace(" (Demo)", "");
18: }
19: 
20: 
21: """One server-side sample policy. An explicit switch overrides the demo/test
22: fallback; selecting a hosted dataset never grants sample visibility."""
23: def samples_visible() -> bool {
24:     raw = os.environ.get("MLOCAL_SHOW_SAMPLES", os.environ.get("MLOCAL_DEMO_MODE", ""));
25:     return raw.strip().lower() in ["1", "true", "yes", "on"];
26: }
27: 
28: # Public catalog nodes are app-owned. HTTP mutations enforce ownership in promo.
29: node Restaurant {
30:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
31:     has slug: str,
32:         name: str,
33:         cuisine: str = "",
34:         blurb: str = "",
35:         merchant_key: str = "",  # Legacy import compatibility; never authorization.
36:         owner_actor_id: str = "",
37:         is_demo: bool = False,
38:         source: str = "manual",
39:         image_url: str = "";
40: }
41: 
42: node Location {
43:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
44:     has address: str,
45:         neighborhood: str = "",
46:         entrance_note: str = "",
47:         note_date: str = "";
48: }
49: 
50: node MenuItem {
51:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
52:     has name: str,
53:         price: float = 0.0,
54:         price_cents: int = -1,
55:         dietary: list[str] = [];
56: }
57: 
58: node Offer {
59:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
60:     has title: str,
61:         description: str = "",
62:         price: float = 0.0,
63:         price_cents: int = -1,
64:         regular_price: float = 0.0,
65:         regular_price_cents: int = -1,
66:         start_ts: float = 0.0,
67:         end_ts: float = 0.0,
68:         quantity: int = 0,
69:         qr_ready: bool = False,  # Old claims require trusted stock reconciliation.
70:         eligibility: str = "Any student with a valid student ID",
71:         terms: str = "",
72:         dietary: list[str] = [],
73:         status: str = "active",
74:         is_demo: bool = False,
75:         menu_item: str = "",
76:         image_url: str = "",
77:         create_key: str = "",
78:         create_digest: str = "",
79:         created_ts: float = 0.0;
80: }
81: 
82: # Credentials and actor IDs never receive public read access.
83: node Redemption {
84:     has student_id: str = "",  # Legacy data only, not an authentication input.
85:         code: str = "",        # Legacy data only, never accepted for redemption.
86:         actor_id: str = "",
87:         restaurant_slug: str = "",
88:         qr_payload: str = "",
89:         offer_title_snapshot: str = "",
90:         price_cents_snapshot: int = 0,
91:         regular_price_cents_snapshot: int = -1,
92:         terms_snapshot: str = "",
93:         eligibility_snapshot: str = "",
94:         status: str = "claimed",
95:         claimed_ts: float = 0.0,
96:         expires_ts: float = 0.0,
97:         redeemed_ts: float = 0.0,
98:         cancelled_ts: float = 0.0;
99: 
100:     # Jac's optional graph visualizer renders repr(node). Never emit private
101:     # fields there, even if the operator accidentally enables that route.
102:     def __repr__ -> str { return "Redemption(private)"; }
103: 
104:     def __jac_access__ -> AccessLevel {
105:         actor = jid(root);
106:         if actor == self.actor_id or (merchant_owner(self.restaurant_slug) == actor) {
107:             return AccessLevel.WRITE;
108:         }
109:         return AccessLevel.NO_ACCESS;
110:     }
111: }
112: 
113: # Public stock accounting reveals no credential, actor or claim ID. Private
114: # Redemption nodes cannot be counted by other students because graph grants filter.
115: node Reservation {
116:     has status: str = "claimed", expires_ts: float = 0.0;
117:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
118: }
119: 
120: edge Reserves: Offer --> Reservation {
121:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
122: }
123: 
124: edge UsesReservation: Redemption --> Reservation {
125:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
126: }
127: 
128: edge HasLocation: Restaurant --> Location {
129:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
130: }
131: 
132: edge Serves: Restaurant --> MenuItem {
133:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
134: }
135: 
136: edge Publishes: Restaurant --> Offer {
137:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
138: }
139: 
140: edge Features: Offer --> MenuItem {
141:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
142: }
143: 
144: edge ClaimedAs: Offer --> Redemption {
145:     def __jac_access__ -> AccessLevel { return AccessLevel.WRITE; }
146: }
147: 
148: """Minutes a claim holds a unit before it is released back to availability."""
149: glob:pub CLAIM_HOLD_MINUTES: int = 20;
150: 
151: glob:pub DIET_TAGS: list[str] = ["vegetarian", "vegan", "gluten-free", "halal"];

1: """Data import boundary.
2: 
3: Every restaurant enters the graph through f"import_restaurant(record)". The demo
4: seed uses it today; a future community-source adapter (CSV, partner feed) only
5: has to produce the same record shape. Offer times in a record are given as
6: hour offsets from import time so demo data is always fresh.
7: """
8: 
9: import time;
10: import math;
11: import from urllib.parse { urlsplit }
12: import from services.money { money_to_cents }
13: import from services.models {
14:     Restaurant,
15:     Location,
16:     MenuItem,
17:     Offer,
18:     HasLocation,
19:     Serves,
20:     Publishes,
21:     Features
22: }
23: import from services.context_models {
24:     ContextNotice,
25:     Affects,
26:     ContextValidationError
27: }
28: 
29: 
30: def _reject_untrusted_identity_fields(record: dict[str, any]) -> None {
31:     for key in ["merchant_key", "owner_actor_id", "password", "role", "roles"] {
32:         if key in record {
33:             raise ContextValidationError("import records cannot assign " + key);
34:         }
35:     }
36: }
37: 
38: 
39: def _notice_location(location_slug: str, is_demo: bool) -> Location {
40:     restaurants = [root.shared -->[?:Restaurant, slug == location_slug]];
41:     # Initial bootstrap creates restaurants under the caller before qr_catalog
42:     # publishes them. Once shared, always resolve the public catalog first.
43:     if not restaurants {
44:         restaurants = [root -->[?:Restaurant, slug == location_slug]];
45:     }
46:     if len(restaurants) != 1 {
47:         raise ContextValidationError("location_slug must resolve to exactly one restaurant");
48:     }
49:     if restaurants[0].is_demo and not is_demo {
50:         raise ContextValidationError("real access notices cannot target fictional restaurants");
51:     }
52:     locations = [restaurants[0] ->:HasLocation:->];
53:     if len(locations) != 1 {
54:         raise ContextValidationError("location_slug must resolve to exactly one location");
55:     }
56:     return locations[0];
57: }
58: 
59: 
60: def _validate_access_notice(record: dict[str, any]) -> None {
61:     _reject_untrusted_identity_fields(record);
62:     required = ["source_id", "external_id", "location_slug", "version", "publisher",
63:                 "source_url", "checked_at", "valid_from", "valid_until", "summary", "is_demo"];
64:     for key in required {
65:         if key not in record {
66:             raise ContextValidationError("missing access notice field: " + key);
67:         }
68:     }
69:     for key in ["source_id", "external_id", "location_slug", "version", "publisher", "summary"] {
70:         if not isinstance(record[key], str) or not record[key].strip() {
71:             raise ContextValidationError("access notice " + key + " must be a non-empty string");
72:         }
73:     }
74:     if not isinstance(record["is_demo"], bool) {
75:         raise ContextValidationError("access notice is_demo must be boolean");
76:     }
77:     if not isinstance(record["source_url"], str) or (not record["is_demo"] and not record["source_url"].strip()) {
78:         raise ContextValidationError("source_url is required unless the fixture is explicitly simulated");
79:     }
80:     source_url = record["source_url"].strip();
81:     if source_url {
82:         try {
83:             parsed = urlsplit(source_url);
84:             if parsed.scheme not in ["http", "https"] or not parsed.hostname or parsed.username is not None or parsed.password is not None {
85:                 raise ContextValidationError("source_url must be an HTTP(S) source without credentials");
86:             }
87:         } except ValueError {
88:             raise ContextValidationError("source_url is malformed");
89:         }
90:     }
91:     for field in ["original_evidence", "normalized_evidence"] {
92:         if field in record and not isinstance(record[field], dict) {
93:             raise ContextValidationError(field + " must be an object");
94:         }
95:     }
96:     for key in ["checked_at", "valid_from", "valid_until"] {
97:         if isinstance(record[key], bool) or not isinstance(record[key], (int, float)) or not math.isfinite(float(record[key])) {
98:             raise ContextValidationError("access notice " + key + " must be a finite timestamp");
99:         }
100:     }
101:     if record["valid_until"] <= record["valid_from"] {
102:         raise ContextValidationError("access notice validity interval must be increasing");
103:     }
104:     if "entrance_instruction" in record and not isinstance(record["entrance_instruction"], str) {
105:         raise ContextValidationError("entrance_instruction must be text when present");
106:     }
107: }
108: 
109: 
110: """Validate, resolve, then atomically create or refresh one source notice.
111: 
112:     Identity is the stable ``(source_id, external_id)`` pair. Every validation
113:     and location lookup happens before graph mutation, so bad input leaves the
114:     existing graph untouched. A source refresh failure should simply not call
115:     this function; that preserves the last successful checked timestamp.
116: """
117: def upsert_access_notice(record: dict[str, any]) -> str {
118:     _validate_access_notice(record);
119:     loc = _notice_location(record["location_slug"], record["is_demo"]);
120:     matches = [root.shared -->[?:ContextNotice, source_id == record["source_id"], external_id == record["external_id"]]];
121:     if len(matches) > 1 {
122:         raise ContextValidationError("ambiguous source/external notice identity");
123:     }
124:     notice: ContextNotice;
125:     if matches {
126:         notice = matches[0];
127:         affected = [notice ->:Affects:->];
128:         if len(affected) > 1 {
129:             raise ContextValidationError("a notice must affect exactly one location");
130:         }
131:         if affected and jid(affected[0]) != jid(loc) {
132:             raise ContextValidationError("a notice identity cannot be silently moved to another location");
133:         }
134:         notice.version = record["version"];
135:         notice.summary = record["summary"];
136:         notice.publisher = record["publisher"];
137:         notice.source_url = record["source_url"].strip();
138:         notice.checked_at = float(record["checked_at"]);
139:         notice.valid_from = float(record["valid_from"]);
140:         notice.valid_until = float(record["valid_until"]);
141:         notice.is_demo = record["is_demo"];
142:         notice.entrance_instruction = record.get("entrance_instruction", "");
143:         notice.original_evidence = record.get("original_evidence", record);
144:         notice.normalized_evidence = record.get("normalized_evidence", {});
145:         if not affected {
146:             notice +>:Affects():+> loc;
147:         }
148:     } else {
149:         notice = ContextNotice(
150:             source_id=record["source_id"], external_id=record["external_id"],
151:             version=record["version"], summary=record["summary"],
152:             publisher=record["publisher"], source_url=record["source_url"].strip(),
153:             checked_at=float(record["checked_at"]), valid_from=float(record["valid_from"]),
154:             valid_until=float(record["valid_until"]), is_demo=record["is_demo"],
155:             entrance_instruction=record.get("entrance_instruction", ""),
156:             original_evidence=record.get("original_evidence", record),
157:             normalized_evidence=record.get("normalized_evidence", {})
158:         );
159:         root.shared ++> notice;
160:         notice +>:Affects():+> loc;
161:     }
162:     return jid(notice);
163: }
164: 
165: 
166: """Small reviewed-JSON adapter; callers retain failed source records separately."""
167: def import_access_notices(records: list[dict[str, any]]) -> list[str] {
168:     return [upsert_access_notice(record) for record in records];
169: }
170: 
171: 
172: """Create one restaurant (with location, menu and offers) from a plain record.
173: 
174: Record keys: slug, name, cuisine, blurb, is_demo, source,
175: location{address, neighborhood, entrance_note, note_date},
176: menu[{name, price, dietary}], offers[{title, description, price, regular_price,
177: start_in_h, end_in_h, quantity, eligibility, terms, dietary, menu_item, status}].
178: Returns the restaurant, or the existing one if the slug is already present.
179: """
180: def import_restaurant(record: dict[str, any]) -> Restaurant {
181:     _reject_untrusted_identity_fields(record);
182:     existing = [root-->[?:Restaurant, slug == record["slug"]]];
183:     if existing {
