{"file_path": "/workspace/services/context.jac", "content": """"Location access context.

Returns only reviewed notices whose single Affects edge points at the requested
location. A notice is current only when it was checked no later than now, at
most ACCESS_NOTICE_MAX_AGE_SECONDS ago, and now lies inside its validity window
[valid_from, valid_until). Anything else needs recheck: provenance is kept, but
the entrance instruction is blanked so stale directions are never presented as
current guidance. Notices with ambiguous associations are never shown.
"""

import from services.models { Location }
import from services.context_models {
    ContextNotice,
    Affects,
    AccessNoticeView,
    AccessContextView
}


"""Maximum age, in seconds, of a source check before a notice needs recheck."""
glob:pub ACCESS_NOTICE_MAX_AGE_SECONDS: float = 86400.0;


"""Classify one notice as current or needs_recheck at time now."""
def _notice_state(notice: ContextNotice, now: float) -> str {
    if notice.checked_at > now {
        return "needs_recheck";
    }
    if now - notice.checked_at > ACCESS_NOTICE_MAX_AGE_SECONDS {
        return "needs_recheck";
    }
    if now < notice.valid_from or now >= notice.valid_until {
        return "needs_recheck";
    }
    return "current";
}


"""Notices whose only Affects target is the given location (deduplicated)."""
def _location_notices(location_id: str) -> list[ContextNotice] {
    seen: dict[str, bool] = {};
    found: list[ContextNotice] = [];
    candidates = [root.shared -->[?:ContextNotice]] + [root -->[?:ContextNotice]];
    for candidate in candidates {
        key = jid(candidate);
        if key in seen {
            continue;
        }
        seen[key] = True;
        affected = [candidate ->:Affects:->];
        if len(affected) == 1 and jid(affected[0]) == location_id {
            found.append(candidate);
        }
    }
    return found;
}


"""Source-labeled access context for one location at time now.

state is none when no notice applies, needs_recheck when any applicable notice
is stale or out of window, and current only when every notice is current.
"""
def get_access_context(location_id: str, now: float) -> AccessContextView {
    views: list[AccessNoticeView] = [];
    for notice in _location_notices(location_id) {
        state = _notice_state(notice, now);
        views.append(
            AccessNoticeView(
                id=jid(notice),
                source_id=notice.source_id,
                external_id=notice.external_id,
                version=notice.version,
                summary=notice.summary,
                publisher=notice.publisher,
                source_url=notice.source_url,
                checked_at=notice.checked_at,
                valid_from=notice.valid_from,
                valid_until=notice.valid_until,
                is_demo=notice.is_demo,
                state=state,
                entrance_instruction=notice.entrance_instruction if state == "current" else ""
            )
        );
    }
    views.sort(key=lambda v: AccessNoticeView: (v.source_id, v.external_id));
    overall = "none";
    if views {
        overall = "current";
        for v in views {
            if v.state != "current" {
                overall = "needs_recheck";
            }
        }
    }
    return AccessContextView(location_id=location_id, state=overall, notices=views);
}
"}

